+/* Today toggle: » send to today, « recall to backlog. */
+li.todo .today-btn {
+  border: none;
+  padding: 0 2px;
+  font-size: 0.95rem;
+  line-height: 1;
+  color: var(--muted);
+  opacity: 0.5;
+  cursor: pointer;
+}
+li.todo.in-today .today-btn {
+  color: var(--accent);
+  opacity: 1;
+}
+li.todo.done .today-btn {
+  display: none;
+}
+
+/* --- bottom dock: Today + Done tabs --- */
+.dock {
+  position: fixed;
+  left: 0;
+  right: 0;
+  bottom: 0;
+  margin: 0 auto;
+  max-width: 560px;
+  background: var(--base01);
+  border-top: 1px solid var(--line);
+  padding-bottom: env(safe-area-inset-bottom);
+  z-index: 10;
+}
+.dock.drop-target {
+  outline: 1px dashed var(--accent);
+  outline-offset: -1px;
+}
+.tabbar {
+  display: flex;
+  align-items: stretch;
+}
+.tabbar .tab {
+  flex: 1;
+  border: none;
+  border-radius: 0;
+  padding: 9px 12px;
+  color: var(--muted);
+  text-align: left;
+  cursor: pointer;
+}
+.tabbar .tab.active {
+  color: var(--fg);
+  box-shadow: inset 0 2px 0 var(--accent);
+}
+.tabbar .chev {
+  border: none;
+  color: var(--muted);
+  padding: 9px 14px;
+  cursor: pointer;
+}
+.dock .panel {
+  display: none;
+  padding: 0 16px 10px;
+  max-height: 45vh;
+  overflow-y: auto;
+}
+.dock.open .panel {
+  display: block;
+}
+.dock .list {
+  margin: 0;
+  border-top: none;
+}
+.done-head {
+  font-size: 0.7rem;
+  text-transform: uppercase;
+  letter-spacing: 0.08em;
+  color: var(--muted);
+  padding: 10px 2px 2px;
+}
+
